function ProcessInputData( dataStream )
{
    // This function orchestrates the calculation of a cumulative sum
    // based on a sequence generated by a specific modular arithmetic rule.

    // First, process the raw input: trim whitespace, split into lines,
    // then split each line into individual string segments.
    let parsedLines = dataStream.trim().split( "\n" ).map( function( elementString ) {
        return elementString.split( " " )
    } );

    // Extract the three main numeric parameters from the initial input line.
    let upperBound = parseInt( parsedLines[0][0], 10 );
    let initialValue = parseInt( parsedLines[0][1], 10 );
    let moduloBase = parseInt( parsedLines[0][2], 10 );

    // Initialize a tracking array to store the iteration count
    // at which each remainder (0 to moduloBase-1) is first encountered.
    // All elements are initially set to zero, indicating unvisited.
    let remainderTracker = new Array( moduloBase ).fill( 0 );

    // Set up variables for the current sequence element and the final accumulated total.
    let currentValue = initialValue;
    let totalResult = 0;

    // A temporary variable to hold the sum of elements within a detected cycle.
    let periodicSum = 0;

    // Mark the initial sequence element's remainder as visited at iteration 1.
    remainderTracker[ currentValue ] = 1;

    // Begin the primary loop, generating sequence elements from the second iteration onwards.
    for ( let iterationCount = 2; iterationCount <= upperBound; iterationCount++ )
    {
        // Calculate the next value in the sequence using the defined rule:
        // (currentValue ^ 2) modulo moduloBase.
        currentValue = calculateRemainder( Math.pow( calculateRemainder( currentValue, moduloBase ), 2 ), moduloBase );

        // Check if this newly computed remainder has been observed before.
        if ( remainderTracker[ currentValue ] === 0 )
        {
            // If it's a new remainder, record the current iteration count.
            remainderTracker[ currentValue ] = iterationCount;
        }
        else
        {
            // A cycle has been identified. Calculate the length of this cycle.
            let cycleLength = iterationCount - remainderTracker[ currentValue ];

            // Iterate through all possible remainders to sum those that are part of the detected cycle.
            for ( let arrayIndex = 0; arrayIndex < moduloBase; arrayIndex++ )
            {
                // Only include remainders that were visited at or after the cycle's start point.
                if ( remainderTracker[ arrayIndex ] >= remainderTracker[ currentValue ] ) {
                    periodicSum += arrayIndex;
                }
            }

            // Add the contribution from full cycles to the total result.
            // This involves counting how many full cycles fit into the remaining iterations
            // and multiplying by the sum of elements in one cycle.
            totalResult += Math.floor( ( upperBound - remainderTracker[ currentValue ] + 1 ) / cycleLength ) * periodicSum;

            // Adjust the upper bound to reflect the iterations already accounted for by the cycles.
            // The remaining iterations will be processed individually.
            upperBound = ( upperBound - remainderTracker[ currentValue ] + 1 ) % cycleLength + remainderTracker[ currentValue ] - 1;
        }
    }

    // After the main loop (and cycle handling), sum up the values of any
    // remaining unique elements in the sequence up to the (potentially adjusted) upperBound.
    for ( let finalIndex = 0; finalIndex < moduloBase; finalIndex++ )
    {
        if ( remainderTracker[ finalIndex ] > 0 && remainderTracker[ finalIndex ] <= upperBound )
        {
            totalResult += finalIndex;
        }
    }

    // Display the final computed sum to the console.
    console.log( totalResult );
}

// A helper function to compute the mathematical modulo, ensuring a non-negative result
// when the dividend is negative, assuming the divisor is positive.
function calculateRemainder( dividendVal, divisorVal )
{
    const intermediateResult = dividendVal % divisorVal;
    return intermediateResult < 0 ? ( intermediateResult + divisorVal ) : intermediateResult;
}


// Read the entire content of standard input as a UTF-8 string
// and pass it to the main processing function to start the computation.
ProcessInputData( require("fs").readFileSync("/dev/stdin", "utf8") );